=== astro.config.mjs ===
// @ts-check
import { defineConfig } from 'astro/config';

import react from '@astrojs/react';
import icon from 'astro-icon';
import mdx from '@astrojs/mdx';
import tailwindcss from '@tailwindcss/vite';

import { unified } from '@astrojs/markdown-remark';
import remarkExternalLinks from './src/utils/plugins/remarkExternalLinks';
import remarkGfm from 'remark-gfm';
import rehypeFootnoteLinks from './src/utils/plugins/rehypeFootnoteLinks';

import sitemap from '@astrojs/sitemap';
import netlify from '@astrojs/netlify';

import { redirects } from './src/constants/redirects';

export default defineConfig({
  site: 'https://agilepainrelief.com',
  output: 'static',
  integrations: [react(), icon(), mdx(), sitemap()],

  markdown: {
    processor: unified({
      remarkPlugins: [remarkExternalLinks, remarkGfm],
      rehypePlugins: [rehypeFootnoteLinks],
    }),
  },

  adapter: netlify({ imageCDN: false }),

  vite: {
    plugins: [tailwindcss()],
  },

  experimental: {
    contentIntellisense: true,
  },

  redirects,
});
=== netlify.toml ===
# Skip Netlify builds when only files under email-automation/ changed
# (it's an internal CLI, not part of the deployed site).
# shared/ is NOT ignored — the signup endpoint imports from it.
[build]
  ignore = "git diff --quiet HEAD^ HEAD -- ':!email-automation'"

# Lead-magnet downloads: served on demand, never indexed by search engines.
[[headers]]
  for = "/downloads/*"
  [headers.values]
    X-Robots-Tag = "noindex, nofollow"

# Course workbooks: unguessable per-course slug, delivered by emailed link only.
# This header is the sole guard (a PDF has no HTML <meta> fallback), so it must
# stay. Deliberately NOT listed in robots.txt: a Disallow would stop crawlers
# fetching the file, so they'd never see this noindex. See CLAUDE.md.
[[headers]]
  for = "/materials/*"
  [headers.values]
    X-Robots-Tag = "noindex, nofollow"
